import { useEffect, useState } from 'react';
import { getMyOrders } from '../services/api';
import './OrdersPage.css';

const STATUS_LABELS = { pending:'Pending', confirmed:'Confirmed', shipped:'Shipped', delivered:'Delivered', cancelled:'Cancelled' };

export default function OrdersPage() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getMyOrders().then(({ data }) => setOrders(data)).finally(() => setLoading(false));
  }, []);

  if (loading) return <div className="page-loader"><div className="spinner" /></div>;

  return (
    <div className="orders-page">
      <h1 className="orders-title">My Orders</h1>
      {orders.length === 0 ? (
        <p className="text-muted">You haven't placed any orders yet.</p>
      ) : (
        orders.map((order) => (
          <div className="order-card" key={order._id}>
            <div className="order-header">
              <div>
                <div className="order-id">Order #{order._id.slice(-8).toUpperCase()}</div>
                <div className="order-date">{new Date(order.createdAt).toLocaleDateString('en-IN', { day:'numeric', month:'long', year:'numeric' })}</div>
              </div>
              <div className="order-right">
                <span className={`badge badge-${order.status}`}>{STATUS_LABELS[order.status]}</span>
                <div className="order-total">₹{order.totalAmount.toLocaleString()}</div>
              </div>
            </div>
            <div className="order-items">
              {order.items.map((item, i) => (
                <div className="order-item" key={i}>
                  <span className="order-item-name">{item.name}</span>
                  <span className="order-item-meta">×{item.quantity} {item.size && `· ${item.size}`}</span>
                  <span>₹{(item.price * item.quantity).toLocaleString()}</span>
                </div>
              ))}
            </div>
            <div className="order-address">
              📍 {order.shippingAddress.street}, {order.shippingAddress.city}, {order.shippingAddress.state} — {order.shippingAddress.pincode}
            </div>
          </div>
        ))
      )}
    </div>
  );
}
